//! Genuine inert live boundaries follow native trees and exact CharacterData.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div id=root>Main</div><input id=neighbor value=seed></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://inert-range.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn range_inert_factories_real_documents_method_realms_native_topology_and_exact_text(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var parsed=new DOMParser().parseFromString('<!doctype html><body><template id=t><span>Saved</span></template></body>','text/html'),content=parsed.getElementById('t').content;
for(var owner of [new Document(),document.implementation.createHTMLDocument('Native'),document.implementation.createDocument(null,'root',null),parsed,content.ownerDocument]){var r=owner.createRange();if(!(r instanceof Range)||r.startContainer!==owner||r.endContainer!==owner||r.startOffset||r.endOffset||!r.collapsed)throw 'actual inert document factory';}
var owner=new Document(),fragment=owner.createDocumentFragment(),a=owner.createTextNode('\uD800A\uDC00'),b=owner.createCDATASection('BC'),comment=owner.createComment('comment'),pi=owner.createProcessingInstruction('p','data');for(var node of [a,comment,b,pi])fragment.appendChild(node);var r=owner.createRange();r.setStart(a,1);r.setEnd(b,1);if(r.commonAncestorContainer!==fragment||r.toString().length!==3||r.toString().charCodeAt(0)!==65||r.toString().charCodeAt(1)!==56320||r.toString().charAt(2)!=='B'||r.comparePoint(comment,3)!==0||r.intersectsNode(pi))throw 'native inert topology and Text CDATA only';r.setEndBefore(b);if(r.endContainer!==fragment||r.endOffset!==2)throw 'native inert relative boundary';var copy=r.cloneRange();r.collapse(true);if(!r.collapsed||copy.collapsed||copy.startContainer!==a)throw 'inert independent live clone';
for(var data of [a,b,comment,pi]){var live=owner.createRange();live.setStart(data,1);live.setEnd(data,2);data.nodeValue='\uD800X\uDC00';if(live.startOffset||live.endOffset||live.startContainer!==data||data.nodeValue.charCodeAt(0)!==55296||data.nodeValue.charCodeAt(2)!==56320)throw 'all inert CharacterData full-write live offsets and exact units';data.replaceData(0,1,'Y');if(live.startOffset||live.endOffset)throw 'inert splice does not shift zero points';}var failed=false;try{r.setStart(pi,5);}catch(e){failed=e instanceof DOMException&&e.name==='IndexSizeError';}if(!failed)throw 'actual inert PI length';failed=false;try{r.selectNodeContents(parsed.doctype);}catch(e){failed=e.name==='InvalidNodeTypeError';}if(!failed)throw 'genuine inert DocumentType boundary';
var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,borrowed=w.Document.prototype.createRange.call(owner);if(!(borrowed instanceof w.Range)||borrowed instanceof Range||borrowed.startContainer!==owner)throw 'canonical method realm independent of inert document owner';
"#);}
#[test]
fn range_inert_tree_removal_moves_fragment_transfers_and_fixed_snapshot_distinction(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('Native'),parent=owner.createElement('div'),a=owner.createElement('a'),b=owner.createElement('b'),c=owner.createElement('i'),text=owner.createTextNode('Exact');parent.appendChild(a);parent.appendChild(b);parent.appendChild(c);b.appendChild(text);var r=owner.createRange();r.setStart(text,1);r.setEnd(text,4);var fixed=new StaticRange({startContainer:text,startOffset:1,endContainer:text,endOffset:4}),edges=owner.createRange();edges.setStart(parent,1);edges.setEnd(parent,3);parent.removeChild(b);if(r.startContainer!==parent||r.endContainer!==parent||r.startOffset!==1||r.endOffset!==1||edges.startOffset!==1||edges.endOffset!==2||fixed.startContainer!==text||fixed.endOffset!==4)throw 'inert removal descendants and strict boundary shifts';parent.insertBefore(b,a);if(edges.startOffset!==2||edges.endOffset!==3)throw 'actual inert insertion shifts';r.selectNodeContents(text);parent.appendChild(b);if(r.startContainer!==parent||r.startOffset!==0||r.endOffset!==0||edges.startOffset!==1||edges.endOffset!==2)throw 'inert move removal precedes insertion';
var fragment=owner.createDocumentFragment(),x=owner.createElement('span'),y=owner.createTextNode('Tail');x.appendChild(y);fragment.appendChild(x);var nested=owner.createRange();nested.setStart(y,2);nested.setEnd(y,4);var whole=owner.createRange();whole.selectNodeContents(fragment);parent.insertBefore(fragment,c);if(nested.startContainer!==fragment||nested.startOffset||nested.endOffset||whole.startOffset||whole.endOffset||fragment.firstChild!==null||x.parentNode!==parent)throw 'native inert fragment removal and insertion';
var replaced=owner.createRange();replaced.selectNodeContents(y);var boundaries=owner.createRange();boundaries.selectNodeContents(parent);parent.replaceChild(b,x);if(replaced.startContainer!==parent||replaced.endContainer!==parent||replaced.startOffset!==1||replaced.endOffset!==1||boundaries.endOffset!==3||parent.childNodes.length!==3)throw 'inert same-parent replacement removes source before outgoing';
var adopted=owner.createRange();adopted.selectNodeContents(text);var destination=new Document();destination.adoptNode(b);if(adopted.startContainer!==parent||adopted.endContainer!==parent||adopted.startOffset!==1||adopted.endOffset!==1||text.ownerDocument!==destination||b.parentNode!==null)throw 'inert adoption removal and actual owner change';
var incoming=owner.createDocumentFragment(),fresh=owner.createElement('span'),freshText=owner.createTextNode('Fragment');fresh.appendChild(freshText);incoming.appendChild(fresh);var sourcePoints=owner.createRange();sourcePoints.selectNodeContents(freshText);var outgoingPoints=owner.createRange();outgoingPoints.selectNodeContents(c);parent.replaceChild(incoming,c);if(sourcePoints.startContainer!==incoming||sourcePoints.endContainer!==incoming||sourcePoints.startOffset||sourcePoints.endOffset||outgoingPoints.startContainer!==parent||outgoingPoints.endContainer!==parent||outgoingPoints.startOffset!==1||outgoingPoints.endOffset!==1||fresh.parentNode!==parent||incoming.firstChild!==null)throw 'inert fragment replacement source and outgoing removal ordering';
var documentRange=owner.createRange();documentRange.setStart(owner.body,0);var wholeDocument=owner.createRange();wholeDocument.selectNodeContents(owner);owner.removeChild(owner.documentElement);if(documentRange.startContainer!==owner||documentRange.endContainer!==owner||documentRange.startOffset!==1||documentRange.endOffset!==1||wholeDocument.endOffset!==1||owner.documentElement!==null)throw 'actual inert Document child removal and metadata synchronization';
"#);}
#[test]
fn range_inert_full_and_spliced_data_split_normalize_replacement_and_promotion_updates(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),fragment=owner.createDocumentFragment(),text=owner.createTextNode('ABCD');fragment.appendChild(text);var r=owner.createRange();r.setStart(text,1);r.setEnd(text,3);text.insertData(0,'X');if(r.startOffset!==2||r.endOffset!==4||r.toString()!=='BC')throw 'inert splice retains offsets';text.data='New';if(r.startOffset||r.endOffset||r.startContainer!==text)throw 'inert full data replacement';r.setStart(text,1);r.setEnd(text,3);fragment.appendChild(owner.createTextNode('!'));var edges=owner.createRange();edges.selectNodeContents(fragment);var tail=text.splitText(1);if(r.startContainer!==text||r.startOffset!==1||r.endContainer!==tail||r.endOffset!==2||edges.endOffset!==3)throw 'inert split native parent and descendant boundaries';fragment.normalize();if(r.startContainer!==text||r.startOffset!==1||r.endContainer!==text||r.endOffset!==3||edges.endOffset!==1||fragment.firstChild!==fragment.lastChild)throw 'inert normalize boundary relocation';fragment.textContent='Replacement';if(r.startContainer!==fragment||r.endContainer!==fragment||r.startOffset||r.endOffset||edges.endOffset)throw 'inert text replacement retargets descendants';
var parsed=new DOMParser().parseFromString('<body><template id=t><span>Before</span></template></body>','text/html'),host=parsed.getElementById('t'),content=host.content,source=content.firstChild.firstChild,live=content.ownerDocument.createRange();live.setStart(source,1);live.setEnd(source,4);host.innerHTML='<b>After</b>';if(live.startContainer!==content||live.endContainer!==content||live.startOffset||live.endOffset)throw 'template replacement native removal';var promote=content.ownerDocument.createRange();promote.selectNodeContents(content.firstChild.firstChild);document.getElementById('root').appendChild(content);if(promote.startContainer!==content||promote.endContainer!==content||promote.startOffset||promote.endOffset||content.firstChild!==null||document.getElementById('root').textContent!=='MainAfter')throw 'inert promotion source removal retargets live boundaries';
"#);}
#[test]
fn range_inert_content_guards_author_conversion_reentry_and_fresh_recovery(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),fragment=owner.createDocumentFragment(),text=owner.createTextNode('Native');fragment.appendChild(text);var r=owner.createRange();r.selectNodeContents(text);var caught=0;for(var fn of [function(){r.cloneContents();},function(){r.extractContents();},function(){r.deleteContents();},function(){r.insertNode(owner.createTextNode('X'));},function(){r.surroundContents(owner.createElement('b'));}]){try{fn();}catch(e){if(e instanceof DOMException&&e.name==='NotSupportedError')caught++;}}if(caught!==5||text.data!=='Native'||r.startOffset||r.endOffset!==6||fragment.firstChild!==text)throw 'inert content producers explicitly refuse before effects';
var calls=0;r.setStart(text,{valueOf:function(){calls++;text.data='XY';return 1;}});if(calls!==1||r.startContainer!==text||r.startOffset!==1||r.endOffset!==1||!r.collapsed)throw 'author conversion observes actual full replacement before boundary publication';var failed=false;try{r.setEnd(text,{valueOf:function(){text.data='Z';return 9;}});}catch(e){failed=e.name==='IndexSizeError';}if(!failed||r.startOffset||r.endOffset||text.data!=='Z')throw 'failed converted boundary retains author mutation prefix';r.selectNodeContents(text);if(r.toString()!=='Z')throw 'fresh native inert recovery';
"#);}
#[test]
fn range_inert_native_record_growth_work_copy_retained_deadline_refusal_and_recovery(){
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var owner=new Document();");p.begin_job();let Value::Host(owner)=p.runtime.execute("owner",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("native Document")};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};bridge.create_range(WINDOW,owner).unwrap();while bridge.state.ranges.len()<bridge.state.ranges.capacity(){bridge.create_range(WINDOW,owner).unwrap();}let before=(bridge.state.retained,bridge.state.ranges.len(),bridge.state.ranges.capacity(),bridge.doc.nodes.len(),bridge.state.dom_commits);let limit=bridge.state.retained_limit;match profile{0=>bridge.state.host_work=0,1=>bridge.state.copy_work=0,2=>bridge.state.retained_limit=bridge.state.retained,_=>{bridge.state.host_work=4096;bridge.state.execution_deadline=Some(Instant::now());}}assert!(bridge.create_range(WINDOW,owner).is_err());assert_eq!((bridge.state.retained,bridge.state.ranges.len(),bridge.state.ranges.capacity(),bridge.doc.nodes.len(),bridge.state.dom_commits),before);bridge.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"var fresh=owner.createRange();if(fresh.startContainer!==owner||!fresh.collapsed)throw 'fresh inert native record recovery';");}
}

#[test]
fn range_inert_native_mutation_work_refusal_preserves_tree_points_and_recovers(){
 for operation in 0..6{for allowance in [0,8,64,512,4096]{
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var parsed=new DOMParser().parseFromString('<body><template id=t><span>Before</span><b>Tail</b></template></body>','text/html'),host=parsed.getElementById('t'),content=host.content,span=content.firstChild,text=span.firstChild,r=content.ownerDocument.createRange(),edges=content.ownerDocument.createRange();r.setStart(text,1);r.setEnd(text,4);edges.selectNodeContents(content);var root=document.getElementById('root');");
  let mut ids=Vec::new();for name in ["content","span","text","host","root"]{let Value::Host(handle)=p.runtime.execute(name,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("native fixture")};ids.push(handle);}
  let before_points:Vec<_>=p.state.ranges.iter().map(|r|(r.start,r.end)).collect();let before_children=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.inert_children(ids[0]).unwrap().to_vec();let before=(p.state.retained,p.state.dom_commits,d.nodes.len(),p.state.ranges.len());let text_before=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.character_data_source(ids[2]).unwrap().code_units().collect::<Vec<_>>();p.begin_job();p.state.host_work=allowance;
  let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=match operation{
   0=>bridge.mutate_inert_children(ids[0],"removeChild",&[Value::Host(ids[1])]).map(|_|()),
   1=>bridge.mutate_inert_children(ids[0],"appendChild",&[Value::Host(ids[1])]).map(|_|()),
   2=>bridge.replace_inert_text_content(ids[0],DomString::from("Replaced")),
   3=>bridge.set_template_html(ids[3],"<i>Replaced</i>"),
   4=>bridge.write_inert_character_data(ids[2],DomString::from("Replaced")),
   _=>bridge.splice_checked_inert_fragment(node_index(ids[4]).unwrap(),ids[0],None).map(|_|()),
  };
  if result.is_err(){assert_eq!((bridge.state.retained,bridge.state.dom_commits,bridge.doc.nodes.len(),bridge.state.ranges.len()),before,"operation {operation}, allowance {allowance}");assert_eq!(bridge.inert_children(ids[0]).unwrap(),before_children);assert_eq!(bridge.character_data_source(ids[2]).unwrap().code_units().collect::<Vec<_>>(),text_before);assert_eq!(bridge.state.ranges.iter().map(|r|(r.start,r.end)).collect::<Vec<_>>(),before_points);}
  else{continue;}
  let source=match operation{0=>"content.removeChild(span);if(r.startContainer!==content||r.startOffset||r.endOffset)throw 'remove recovery';",1=>"content.appendChild(span);if(r.startContainer!==content||r.startOffset||r.endOffset)throw 'move recovery';",2=>"content.textContent='Replaced';if(r.startContainer!==content||r.startOffset||r.endOffset)throw 'text replacement recovery';",3=>"host.innerHTML='<i>Replaced</i>';if(r.startContainer!==content||r.startOffset||r.endOffset)throw 'template replacement recovery';",4=>"text.data='Replaced';if(r.startContainer!==text||r.startOffset||r.endOffset)throw 'full data recovery';",_=>"root.appendChild(content);if(r.startContainer!==content||r.startOffset||r.endOffset)throw 'promotion recovery';"};run(&mut d,&mut f,&mut p,source);
 }}
}
